#include <flint/fmpq_mpoly.h>
#include <cassert>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void read(istream&in,Poly&p,int dim){int n;in>>n;ulong ex[3]={};string c;fmpq_t q;fmpq_init(q);for(int i=0;i<n;i++){in>>c;assert(!fmpq_set_str(q,c.c_str(),10));fmpq_canonicalise(q);assert(fmpz_fdiv_ui(fmpq_denref(q),32003));for(int j=0;j<dim;j++)in>>ex[j];fmpq_mpoly_push_term_fmpq_ui(p.p,q,ex,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);fmpq_clear(q);}
void write(ostream&out,const Poly&p,int dim){ulong ex[3];fmpq_t c;fmpq_init(c);int n=fmpq_mpoly_length(p.p,ctx);out<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(c,p.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,p.p,i,ctx);char*s=fmpq_get_str(nullptr,10,c);out<<' '<<s;flint_free(s);for(int j=0;j<dim;j++)out<<' '<<ex[j];}out<<'\n';fmpq_clear(c);}
int main(int argc,char**argv){assert(argc==6);auto start=chrono::steady_clock::now();ifstream in(argv[1]),lead(argv[2]),ker(argv[3]);ofstream out(argv[4]),o0(argv[5]);assert(in&&lead&&ker&&out&&o0);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{int nr,nc,n,r,k;in>>nr>>nc;lead>>n>>n>>r>>k;assert(nr==nc&&n==nr&&r+k==n);vector<int>rows(r),cols(r),free(k);for(int&i:rows)lead>>i;for(int&i:cols)lead>>i;for(int&i:free)lead>>i;vector<vector<Poly>>A(n,vector<Poly>(n)),B(n,vector<Poly>(n));for(auto&row:A)for(auto&p:row)read(in,p,3);for(int i=0;i<n;i++)for(int j=0;j<r;j++)B[i][j]=A[i][cols[j]];Poly delta;fmpq_mpoly_gen(delta.p,2,ctx);for(int c=0;c<k;c++){string s;int t;ker>>s>>t;assert(s=="KERNEL"&&t==c);Poly den;read(ker,den,2);vector<Poly>K(n);for(auto&p:K)read(ker,p,2);for(int j=0;j<k;j++)assert(j==c?fmpq_mpoly_equal(K[free[j]].p,den.p,ctx):fmpq_mpoly_is_zero(K[free[j]].p,ctx));bool unit=false;fmpq_t q;fmpq_init(q);for(int j=0;j<fmpq_mpoly_length(den.p,ctx);j++){fmpq_mpoly_get_term_coeff_fmpq(q,den.p,j,ctx);assert(fmpz_fdiv_ui(fmpq_denref(q),32003));if(fmpz_fdiv_ui(fmpq_numref(q),32003))unit=true;}fmpq_clear(q);assert(unit);for(int i=0;i<n;i++){Poly z,tmp;for(int j=0;j<n;j++)if(!fmpq_mpoly_is_zero(K[j].p,ctx)&&!fmpq_mpoly_is_zero(A[i][j].p,ctx)){fmpq_mpoly_mul(tmp.p,A[i][j].p,K[j].p,ctx);fmpq_mpoly_add(z.p,z.p,tmp.p,ctx);}assert(fmpq_mpoly_divides(B[i][r+c].p,z.p,delta.p,ctx));}cerr<<"COLUMN "<<c<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}out<<n<<' '<<n<<'\n';o0<<n<<' '<<n<<'\n';long terms=0,leadingterms=0;fmpq_t q;fmpq_init(q);ulong ex[3];for(auto&row:B)for(auto&p:row){write(out,p,3);Poly c;terms+=fmpq_mpoly_length(p.p,ctx);for(int j=0;j<fmpq_mpoly_length(p.p,ctx);j++){fmpq_mpoly_get_term_exp_ui(ex,p.p,j,ctx);if(ex[2])continue;fmpq_mpoly_get_term_coeff_fmpq(q,p.p,j,ctx);fmpq_mpoly_push_term_fmpq_ui(c.p,q,ex,ctx);}fmpq_mpoly_sort_terms(c.p,ctx);leadingterms+=fmpq_mpoly_length(c.p,ctx);write(o0,c,2);}fmpq_clear(q);out.flush();o0.flush();assert(out.good()&&o0.good());cerr<<"PEEL_PASS "<<k<<" TERMS "<<terms<<" LEADING "<<leadingterms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
